-- Rifts World Book 17: Warlords of Russia, batch 2a: the weapons.
-- 35 new gear rows from Russian Weapons (printed 177-185) and Weapons Unique
-- to the Sovietski (printed 224).
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-warlords-of-russia-weapons.sql
--
-- ALL 35 ARE NEW - catalog-diff --table gear --remote and a slug query,
-- 2026-10-01. The chapter's other Vibro-Blades (Knife, Saber, Sword, Spear,
-- Claws) are held from Rifts Ultimate Edition and Spirit West and are left
-- alone: the catalog wins. See docs/surveys/warlords-of-russia.md.
--
-- THREE PAGES WERE READ OFF A RENDER, NOT THE CACHE. Printed 180, 183 and 184
-- set each weapon's stat block in a second column beside its description and
-- art, and both the cache and read-columns.py return the blocks out of order:
-- the Belofsky Heavy Laser's range, the Plasma Cannon's, the Lynx's damage
-- and the three rifles on printed 184 all land under the wrong heading.
-- Every figure on those three pages was assigned from a 110 dpi render.
--
-- THE DIGIT CIPHER: the cache prints 1D4x10 and 1D6x10 with a ! for the 1 and
-- lO for 10 on every rail gun and launcher here. Read as the dice expression
-- each can only be; the renders of printed 180 and 183 show them plainly.
--
-- WHAT THE BOOK ITSELF GETS WRONG, recorded and not corrected:
--   AR-41      belt is 400 rounds on the weight line, 300 on the payload line.
--   AR-M45     50 M.D.C. on the weight line, 40 on the cost line. 50 stored.
--   AR-M50     90 M.D.C. on the weight line, 45 on the cost line. 90 stored.
--   G-Clip     one price, 4,500, printed for both the short and the long clip.
--   G-293M     no damage printed for its explosive rounds; 800 feet is given
--              as 224 m.
--   S-1000     a grenade burst is two attacks on one line and one on another.
--   Heavy Cyber-Shield  one weight for both sizes. Two rows, one per size,
--              each with its own M.D.C. and price.
--
-- A MISSILE LAUNCHER'S cost IS THE LAUNCHER; missile prices are in cost_note.
-- The Vibro-Scythe Polearm belongs to the Avenging Angel Shocktrooper
-- (printed 131-132) and ships with that batch, not this one.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('e-clip-adaptor', 'E-Clip Adaptor', 'rifts', 'gear', NULL, 1000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Western E-Clips (NGR/Triax and Coalition types included) are too narrow for Russian weapons. The clip snaps into the adaptor and the adaptor into the weapon.', 'Rifts World Book 17: Warlords of Russia p.177'),
('e-pack', 'E-Pack', 'rifts', 'gear', NULL, 35000, '35,000 credits for the pack; 7,000 to recharge it.', NULL, 0, NULL, 'Roughly four standard E-Clips when used in a weapon. Runs 4-6 light machines for 72 hours, or a jet pack, vehicle or generator for about 24.', NULL, NULL, NULL, NULL, 'An energy pack about half the size of a backpack, worn on the hip or back (two or three fit on a human back), with a cabled plug shaped like an E-Clip.', 'Rifts World Book 17: Warlords of Russia p.178'),
('g-clip', 'G-Clip', 'rifts', 'gear', NULL, 4500, 'The book prints 4,500 credits for the short clip and 4,500 for the long clip. Excellent availability.', NULL, 0, NULL, 'Short clip up to 20 shots; long clip 50 shots', NULL, NULL, NULL, NULL, 'The Russian long energy clip, double the capacity of a standard E-Clip and a little wider than NGR and Coalition types; common to weapons made in Russia, Ukraine, Yugoslavia, Mongolia and parts of China. Where it loads differs from weapon to weapon.', 'Rifts World Book 17: Warlords of Russia p.178'),
('war-knight-combat-shield', 'War-Knight Combat Shield', 'rifts', 'armor', 15, 12000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'A small to medium Mega-Damage shield used by War-Knights, Bogatyr and cavalry to parry M.D. melee weapons. Blocking bullets, rail gun bursts, energy blasts or magic bolts is a straight roll at -8 to parry; thrown weapons are a straight roll at -3. It takes damage only when blocking energy blasts or explosions, or when deliberately targeted.', 'Rifts World Book 17: Warlords of Russia p.178'),
('heavy-cyber-shield-small', 'Heavy Cyber-Shield (Small)', 'rifts', 'armor', 70, 20000, 'The book prints one weight, 70 pounds, for both sizes.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'The human-sized Heavy Cyber-Shield, four feet tall: a hydraulic shield of sliding panels that clamps to the forearm of body armor, power armor or a bionic limb. Needs a P.S. of 25 or higher. Blocking bullets, rail gun bursts, energy blasts or magic bolts is a straight roll at -8 to parry; thrown weapons are a straight roll at -3.', 'Rifts World Book 17: Warlords of Russia p.178'),
('heavy-cyber-shield-large', 'Heavy Cyber-Shield (Large)', 'rifts', 'armor', 70, 26000, 'The book prints one weight, 70 pounds, for both sizes.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 90, 'The large Heavy Cyber-Shield, up to six feet tall: a hydraulic shield of sliding panels that clamps to the forearm of body armor, power armor or a bionic limb. Needs a P.S. of 25 or higher. Blocking bullets, rail gun bursts, energy blasts or magic bolts is a straight roll at -8 to parry; thrown weapons are a straight roll at -3.', 'Rifts World Book 17: Warlords of Russia p.178'),
('servo-harness-rig', 'Servo-Harness Rig', 'rifts', 'gear', NULL, 8000, 'Market cost 8,000 credits; 2,200 for the Warlords to make.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A shoulder, back and chest harness with a gyro-stabilizer and light hydraulics, worn over body armor, with a modular connector for most heavy weapons of Russian make. A wearer with a P.S. as low as 9 can carry and use a weapon weighing up to twice his own body weight. The weapon is worn under one arm or over the shoulder.', 'Rifts World Book 17: Warlords of Russia p.178'),
('ar-36-clenched-fist-light-rail-gun', 'AR-36 "Clenched Fist" Light Rail Gun', 'rifts', 'weapon', 30, 30000, 'Market cost 30,000 credits. Most humans need a Servo-Harness Rig unless P.S. is 24 or greater: without one, -10% to climb and prowl, speed reduced 40%, and no acrobatics, gymnastics or swimming; with one, only the last three remain impossible.', '3D6 M.D. per burst of 10 rounds', 1, '3,000 feet (914 m)', '100 round mini-clip (10 bursts), 300 round belt (30 bursts) or 1,200 round drum (120 bursts)', 'Bursts of 10 rounds only; each burst is one melee attack', NULL, NULL, 40, 'Anti-personnel. A light, rugged bullpup rail gun popular among Reavers, powered by a G-Clip or a feed from a cyborg. Heavy Machines and Shocktroopers can use one in each hand; ordinary humans and Light Machines use it two-handed, or one-handed at -3 to strike. The gun weighs 30 pounds; a short clip adds 8, a belt 12 and a drum 50.', 'Rifts World Book 17: Warlords of Russia p.179'),
('ar-41-howler-rail-gun', 'AR-41 "Howler" Rail Gun', 'rifts', 'weapon', 100, 60000, 'Market cost 60,000 credits. Humans need a Servo-Harness Rig to handle it.', '4D6 M.D. per burst of 15 rounds', 1, '4,000 feet (1200 m)', '120 round mini-clip (8 bursts), 300 round belt (20 bursts) or 2,000 round drum (133 bursts)', 'Bursts of 15 rounds only; each burst is one melee attack', NULL, NULL, 80, 'Assault. The medium rail gun of the series, bullpup with a top-loading banana clip and built-in shock absorption. The gun weighs 100 pounds plus an E-Pack; dual clips add 15, a belt 20 and a drum 100. The weight line gives the belt 400 rounds and the payload line 300.', 'Rifts World Book 17: Warlords of Russia p.179'),
('ar-44-sledgehammer-rail-gun', 'AR-44 "Sledgehammer" Rail Gun', 'rifts', 'weapon', 150, 80000, 'Market cost 80,000 credits. Humans need a Servo-Harness Rig to handle it.', '1D4x10 M.D. per burst of 20 rounds', 1, '4,000 feet (1200 m)', '200 round clip (10 bursts), 500 round belt (25 bursts) or 3,000 round drum (150 bursts)', 'Bursts of 20 rounds only; each burst is one melee attack', NULL, NULL, 100, 'Anti-armor and anti-monster. A heavy rail gun with a very high rate of fire, used extensively by Warlords Burgasov, Kolodenko, Seriyev and Sokolov. The gun weighs 150 pounds plus an E-Pack; a clip adds 20, a belt 35 and a drum 140.', 'Rifts World Book 17: Warlords of Russia p.179'),
('ar-60-nikita-super-rail-gun', 'AR-60 "Nikita" Super-Rail Gun', 'rifts', 'weapon', 250, 110000, 'Market cost 110,000 credits. Humans need a Servo-Harness Rig to handle it.', '1D6x10 M.D. per burst of 20 rounds', 1, '5,000 feet (1520 m)', '100 round clip (5 bursts), 500 round belt (25 bursts) or 3,000 round drum (150 bursts)', 'Bursts of 20 rounds only; each burst is one melee attack', NULL, NULL, 120, 'Anti-armor and anti-monster. A very large rail gun with a padded rest worn over the shoulder. Heavy Machines and Shocktroopers can use it; most humans and Light Machines cannot handle it even with a Rig. The gun weighs 250 pounds plus an E-Pack; a clip adds 20, a belt 45 and a drum 180.', 'Rifts World Book 17: Warlords of Russia p.179-180'),
('ar-110-razor-disk-cannon', 'AR-110 Razor Disk Cannon', 'rifts', 'weapon', 150, 80000, 'Market cost 80,000 credits, plus an 8,000 credit Rig for a human to handle it.', '1D6 M.D. per disc; 1D6x10 M.D. per burst of 10 discs', 1, '2,000 feet (610 m)', '200 round belt (20 bursts) or 2,000 round drum (200 bursts)', 'One at a time, or a 10 round burst that counts as two melee attacks', NULL, NULL, 80, 'Anti-armor and anti-monster. A wide, flat rail gun on a lateral-magnetic rail that fires M.D.C. discs about twice the size of a compact disc; much shorter ranged than a true rail gun. Humans need a Servo-Rig. The gun weighs 150 pounds plus an E-Pack; a belt adds 35 and a drum 180.', 'Rifts World Book 17: Warlords of Russia p.180'),
('ar-210-grapeshot-cannon', 'AR-210 Grapeshot Cannon', 'rifts', 'weapon', 200, 100000, 'Market cost 100,000 credits, plus an 8,000 credit Rig for a human to handle it.', '1D6 M.D. per round; 1D6x10 M.D. per burst of 10 against a target under 3,500 feet. Past that the grapeshot does 3D6 M.D. (1 M.D. from a single shot) to everything in a 12 foot wide area, or 1D6x10 M.D. (1D6 from a single shot) to one tank- or building-sized target.', 1, '4,000 feet (1200 m)', '100 round belt (10 bursts) or 1,000 round drum (100 bursts)', 'One at a time, or a 10 round burst that counts as two melee attacks', NULL, NULL, 100, 'Anti-armor and anti-monster. Fires M.D.C. rockets that burst on impact or at 3,500 feet, scattering metal balls shotgun-style for another 500 feet. The burst can instead be set for 1,000 feet (1,500 total) against infantry. A favorite of Warlords Orloff and Sokolov. The gun weighs 200 pounds plus an E-Pack; a belt adds 35 and a drum 180.', 'Rifts World Book 17: Warlords of Russia p.180-181'),
('ar-m36-rifle-mini-missile-launcher', 'AR-M36 Rifle Mini-Missile Launcher', 'rifts', 'weapon', 50, 19000, 'Market cost 19,000 credits for the launch-rifle. Light mini-missiles are 2,000 credits each and heavy ones 3,500.', 'Varies by mini-missile type; typically 1D4x10 M.D.', 1, 'One mile (1.6 km)', 'Eight mini-missiles, hand loaded; reloading takes two melee rounds. A spare pack of eight rides in a 20 M.D.C. case weighing 30 pounds.', 'One, or volleys of 2, 3 or 4', NULL, NULL, 40, 'Anti-aircraft and flying monsters; secondarily anti-armor and cyborgs. A front-heavy rifle-style launcher used by humans and Light Machines with a Servo-Rig, or one-handed by Heavy Machines. 50 pounds, plus 20 fully loaded.', 'Rifts World Book 17: Warlords of Russia p.181'),
('ar-m40-dual-launcher', 'AR-M40 Dual Launcher', 'rifts', 'weapon', 50, 15000, 'Market cost 15,000 credits for the launcher. Light mini-missiles are 2,000 credits each and heavy ones 3,500. Wooden stakes are about 5 credits each.', 'Varies by mini-missile type; typically 1D4x10 M.D. Wooden stakes: 2D6 S.D.C. per shaft, 4D6 S.D.C. per twin shafts, 6D6 S.D.C./H.P. for a burst of four.', 1, 'Mini-missiles one mile (1.6 km); wooden stakes 1,000 feet (305 m)', 'Four mini-missiles, hand loaded, and 40 stakes', 'Mini-missiles: 1 or 2. Wooden stakes: 1-4.', NULL, NULL, 40, 'Anti-vampire; secondarily anti-personnel and riot control. A small launcher that hooks to a Servo-Rig (two-handed for a human even so) or is hand-held by Heavy Machines. The top fires mini-missiles and the lower front launchers fire wooden stakes. 50 pounds, plus 20 fully loaded.', 'Rifts World Book 17: Warlords of Russia p.181'),
('ar-m45-cyborg-missile-launcher', 'AR-M45 Cyborg Missile Launcher', 'rifts', 'weapon', 80, 25000, 'Market cost 25,000 credits for the launcher. Light mini-missiles are 2,000 credits each and heavy ones 3,500.', 'Varies by mini-missile type; typically 1D4x10 M.D.', 1, 'One mile (1.6 km)', '12 mini-missiles, hand loaded; reloading takes three melee rounds. A spare pack of eight rides in a 20 M.D.C. case weighing 30 pounds.', 'One, or volleys of 2, 3 or 4', NULL, NULL, 50, 'Anti-aircraft and flying monsters; secondarily anti-armor and cyborgs. Shoulder mounted on Heavy Machines and Shocktroopers, or Servo-Rig mounted with a rear handle and trigger. 80 pounds, plus 30 fully loaded. The weight line gives the weapon 50 M.D.C. and the cost line 40; both are recorded and 50 is stored.', 'Rifts World Book 17: Warlords of Russia p.181-182'),
('ar-m50-heavy-missile-launcher', 'AR-M50 Heavy Missile Launcher', 'rifts', 'weapon', 140, 45000, 'Market cost 45,000 credits for the launcher. Light mini-missiles are 2,000 credits each and heavy ones 3,500.', 'Varies by mini-missile type; typically 1D4x10 M.D.', 1, 'One mile (1.6 km)', '18 mini-missiles, hand loaded; reloading takes four melee rounds. A spare pack of eight rides in a 20 M.D.C. case weighing 30 pounds.', 'One, or volleys of 2, 3 or 4', NULL, NULL, 90, 'Anti-aircraft and flying monsters; secondarily anti-armor and cyborgs. A massive launcher, shoulder mounted on Heavy Machines and Shocktroopers or Servo-Rig mounted; awkward for humans even with a Rig. 140 pounds, plus 44 fully loaded. The weight line gives the weapon 90 M.D.C. and the cost line 45; both are recorded and 90 is stored.', 'Rifts World Book 17: Warlords of Russia p.182'),
('belofsky-double-dealer-laser-cannon', 'Belofsky Double-Dealer Laser Cannon', 'rifts', 'weapon', 60, 65000, 'Market cost 65,000 credits.', 'Laser 3D6 M.D.; ion blaster 5D6 M.D.', 1, 'Laser 3,000 feet (914 m); ion 2,000 feet (610 m)', 'About 10 shots from a standard E-Clip and 100 from an E-Pack; uses a dual pack system', 'Each blast is one melee attack; the two cannot fire together', NULL, NULL, 90, 'Assault. A massive four-barreled weapon: a heavy laser on top, a short-range ion blaster below and a scope at the side. Two-handed for Light Machines and humans with a P.S. of 22, one-handed for Heavy Machines and Shocktroopers. The gun weighs 60 pounds; its backpack of two E-Packs weighs 55.', 'Rifts World Book 17: Warlords of Russia p.182'),
('g-410c-goldbeam-laser-cannon', 'G-410C Goldbeam Laser Cannon', 'rifts', 'weapon', 135, 124000, 'Market cost 124,000 credits.', '3D6 M.D. per single blast, 6D6 M.D. per double blast, or 1D6x10+10 M.D. for a rapid-fire burst from all four lasers', 1, '2,800 feet (853 m)', '20 single shots, 10 dual shots or 5 four-laser bursts from a standard E-Clip, or 50 from an E-Pack; typically a dual E-Pack system', 'Each blast or burst is one melee attack', NULL, NULL, 70, 'A shoulder-mounted cannon of four lasers fired singly, in pairs or all at once. Used by Heavy Machines and Shocktroopers, by Light Machines with a Servo-Rig, and mounted on cavalry vehicles as a support weapon. 135 pounds; its backpack of two E-Packs weighs 55.', 'Rifts World Book 17: Warlords of Russia p.182'),
('belofsky-heavy-laser-cannon', 'Belofsky Heavy Laser Cannon', 'rifts', 'weapon', 200, 90000, 'Market cost 90,000 credits.', '1D6x10+10 M.D.; all four barrels fire together', 1, '3,000 feet (914 m)', 'Three shots from a standard E-Clip, or 50 from an E-Pack; typically a dual E-Pack system', 'Each blast is one melee attack', NULL, NULL, 110, 'Anti-vehicle. A massive four-barreled heavy laser with longer range and payload, worn with a Servo-Rig. The gun weighs 200 pounds; its backpack weighs 55.', 'Rifts World Book 17: Warlords of Russia p.182-183'),
('belofsky-plasma-cannon', 'Belofsky Plasma Cannon', 'rifts', 'weapon', 170, 145000, 'Market cost 145,000 credits.', '1D4x10+10 M.D.', 1, '1,800 feet (548.6 m)', 'Four shots from a standard E-Clip and 70 from an E-Pack; typically a dual E-Pack system', 'Each blast is one melee attack', NULL, NULL, 100, 'Anti-vehicle and anti-monster. A massive plasma weapon that needs a Servo-Rig for humans; Heavy Machines and Shocktroopers use it two-handed. The gun weighs 170 pounds; its backpack weighs 55.', 'Rifts World Book 17: Warlords of Russia p.183'),
('lynx-laser-rifle', 'Lynx Laser Rifle', 'rifts', 'weapon', 6, 19000, 'Market cost 19,000 credits.', '2D6 M.D. per single blast, or 4D6 M.D. for a dual simultaneous blast (one melee attack)', 1, '1,800 feet (548.6 m)', '20 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 35, 'A sturdy, reliable dual-barrel laser rifle popular among Reavers, Huntsmen, assassins and adventurers. It takes either E-Clips or G-Clips.', 'Rifts World Book 17: Warlords of Russia p.183'),
('homesteader-ion-beam-rifle', '"Homesteader" Ion Beam Rifle', 'rifts', 'weapon', 9, 21000, 'Black Market cost 21,000 credits.', '4D6 M.D.', 1, '1,700 feet (518 m)', '12 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 40, 'A heavy ion rifle popular among Reavers and soldiers of all kinds.', 'Rifts World Book 17: Warlords of Russia p.183'),
('big-bear-plasma-rifle', 'Big Bear Plasma Rifle', 'rifts', 'weapon', 14, 29000, 'Market cost 29,000 credits. Outlawed by the Warlords outside their own War Camps; traded briskly on the Black Market all the same.', '5D6 M.D. per single shot', 1, '1,600 feet (488 m)', '10 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 50, 'A heavy assault plasma rifle popular among War-Knights, Heavy Machines and adventurers, the Huntsman-Trapper especially.', 'Rifts World Book 17: Warlords of Russia p.184'),
('g-295r-steamer-pulse-laser-rifle', 'G-295R "Steamer" Pulse Laser Rifle', 'rifts', 'weapon', 15, 32000, 'Market cost 32,000 credits.', '4D6 M.D. per single shot', 1, '2,200 feet (670 m)', '14 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 45, 'A long-range heavy laser rifle usable as a single-shot sniper rifle, with laser targeting and a telescopic sight as standard. Popular among War-Knights, Heavy Machines and adventurers, the Huntsman-Trapper especially.', 'Rifts World Book 17: Warlords of Russia p.184'),
('g-294r-toughman-laser-rifle', 'G-294R "Toughman" Laser Rifle', 'rifts', 'weapon', 13, 32000, 'Market cost 32,000 credits.', '3D6 M.D. per single shot', 1, '1,600 feet (488 m)', '20 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 50, 'A rugged standard laser rifle, in use for over 60 years, that keeps working at 150 degrees Fahrenheit below freezing where most others jam at 100 below.', 'Rifts World Book 17: Warlords of Russia p.184'),
('g-293m-fat-boy-laser', 'G-293M "Fat Boy" Laser', 'rifts', 'weapon', 6, 32000, 'Market cost 32,000 credits.', 'Laser 3D6 M.D. per single shot. The book prints no damage for the explosive rounds.', 1, 'Laser 1,000 feet (305 m); grenades 800 feet (the book prints 224 m)', 'Laser: 20 shots from a standard E-Clip. Grenades: six rounds, hand loaded in one melee round.', 'Each blast is one melee attack', NULL, NULL, 30, 'A short-barrel laser with an over-and-under pump launcher that fires explosive rounds from the lower barrel, a copy of the Triax pump pistol. A favorite of Reavers, War-Knights, Huntsmen and adventurers.', 'Rifts World Book 17: Warlords of Russia p.185'),
('g-21p-laser-pistol', 'G-21P Laser Pistol', 'rifts', 'weapon', 4, 12000, 'Market cost 12,000 credits.', '2D6 M.D. per single shot', 1, '900 feet (274 m)', '20 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 30, 'A heavy laser sidearm found throughout Russia.', 'Rifts World Book 17: Warlords of Russia p.185'),
('g-27p-ion-pistol', 'G-27P Ion Pistol', 'rifts', 'weapon', 4, 12000, 'Market cost 12,000 credits.', '4D6 M.D. per single shot', 1, '500 feet (152 m)', '20 shots from a standard E-Clip', 'Each blast is one melee attack', NULL, NULL, 30, 'A sidearm found throughout Russia: more damage than the laser pistol at shorter range, and reliable underwater and in freezing cold.', 'Rifts World Book 17: Warlords of Russia p.185'),
('vibro-axe', 'Vibro-Axe', 'rifts', 'weapon', NULL, NULL, 'The book prints no price.', '2D6 M.D. (3D6 or 4D6 M.D. if giant-sized)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Vibro-Blade axe. The matching ancient weapon proficiency and its bonuses apply.', 'Rifts World Book 17: Warlords of Russia p.185'),
('vibro-polearm', 'Vibro-Polearm', 'rifts', 'weapon', NULL, NULL, 'The book prints no price.', '3D6 M.D. for a large-bladed polearm, which most are (4D6 M.D. if truly giant-sized)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Vibro-Blade polearm. The matching ancient weapon proficiency and its bonuses apply.', 'Rifts World Book 17: Warlords of Russia p.185'),
('vibro-sword-for-bots', 'Vibro-Sword for Bots (giant-size)', 'rifts', 'weapon', NULL, NULL, 'The book prints no price.', '3D6 M.D. to 4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A giant-sized Vibro-Sword for robots. The matching ancient weapon proficiency and its bonuses apply.', 'Rifts World Book 17: Warlords of Russia p.185'),
('s-20-20-popper-assault-pistol', 'S-20-20 "Popper" Assault Pistol', 'rifts', 'weapon', 11, 50000, 'Black Market cost 50,000 credits and up. Extremely rare: the design is exclusive to the Sovietski and there are no knock-offs.', 'Laser: 2D6 M.D. single beam or 4D6 M.D. double beam (one melee attack). Grenade: 5D6 M.D., blast radius four feet; no bursts.', 1, 'Laser 800 feet (244 m); grenade launcher 600 feet (183 m)', 'Laser: 20 shots per E-Clip, from a side-mounted G- or E-Clip, with room for a second E-Clip in the handle (40 total). Grenades: six, hand loaded in one melee round.', 'Each single or double blast is one melee attack; a grenade is one melee action. Laser and grenade cannot fire together.', NULL, NULL, 50, 'Heavy assault and defense. A double-barreled laser under a rapid-fire grenade launcher, built for cyborgs. One-handed use needs a P.S. of 21; P.S. 16-20 is -3 to strike and weaker is -6, or -1 with two hands. 11 pounds loaded, 10 without the grenades.', 'Rifts World Book 17: Warlords of Russia p.224'),
('s-500-cyclone-pulse-laser-rifle', 'S-500 "Cyclone" Pulse Laser Rifle', 'rifts', 'weapon', 45, 100000, 'Black Market cost 100,000 credits and up. Extremely rare: the design is exclusive to the Sovietski and there are no knock-offs.', '1D6x10 M.D. per pulse blast; a switch selects a single precision shot of 2D6 M.D.', 1, '3,000 feet (914 m)', 'Four shots from a standard E-Clip, or 60 from the E-Pack that is standard issue', 'Each blast is one melee attack', NULL, NULL, 90, 'Anti-monster and assault; secondarily anti-personnel and defense. A large rapid-fire laser firing four near-simultaneous pulses, built for Light and Heavy Machines. A human needs a Servo-Rig or a P.S. of 25.', 'Rifts World Book 17: Warlords of Russia p.224'),
('s-1000-thunderhead-assault-rifle', 'S-1000 "Thunderhead" Assault Rifle', 'rifts', 'weapon', 90, 140000, 'Black Market cost 140,000 credits and up. Extremely rare: the design is exclusive to the Sovietski and there are no knock-offs.', 'Heavy laser: 4D6 M.D. Grenades: 5D6 M.D. each, singly or in a burst of 2-4 at one target; blast radius four feet however many are fired.', 1, 'Laser 2,000 feet (610 m); grenade launcher 1,200 feet (366 m)', 'Laser: 100 shots per E-Pack or 14 per standard E-Clip. Grenades: 32; four minutes to reload by hand, or one melee round to fit a preloaded 28 pound canister.', 'A laser blast is one melee attack. The damage line counts a grenade burst as two melee attacks and the rate of fire line as one action; both are recorded. Laser and grenade cannot fire together.', NULL, NULL, 100, 'Anti-armor and monsters; secondarily anti-personnel and defense. A heavy laser with a self-loading grenade launcher, built for cyborgs. A human needs a Servo-Rig or supernatural P.S. 90 pounds loaded, 62 without the grenades and canister.', 'Rifts World Book 17: Warlords of Russia p.224');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 35 Warlords of Russia weapon rows are in' AS assertion, count(*) AS got, 35 AS want
  FROM gear WHERE slug IN ('e-clip-adaptor', 'e-pack', 'g-clip', 'war-knight-combat-shield', 'heavy-cyber-shield-small', 'heavy-cyber-shield-large', 'servo-harness-rig', 'ar-36-clenched-fist-light-rail-gun', 'ar-41-howler-rail-gun', 'ar-44-sledgehammer-rail-gun', 'ar-60-nikita-super-rail-gun', 'ar-110-razor-disk-cannon', 'ar-210-grapeshot-cannon', 'ar-m36-rifle-mini-missile-launcher', 'ar-m40-dual-launcher', 'ar-m45-cyborg-missile-launcher', 'ar-m50-heavy-missile-launcher', 'belofsky-double-dealer-laser-cannon', 'g-410c-goldbeam-laser-cannon', 'belofsky-heavy-laser-cannon', 'belofsky-plasma-cannon', 'lynx-laser-rifle', 'homesteader-ion-beam-rifle', 'big-bear-plasma-rifle', 'g-295r-steamer-pulse-laser-rifle', 'g-294r-toughman-laser-rifle', 'g-293m-fat-boy-laser', 'g-21p-laser-pistol', 'g-27p-ion-pistol', 'vibro-axe', 'vibro-polearm', 'vibro-sword-for-bots', 's-20-20-popper-assault-pistol', 's-500-cyclone-pulse-laser-rifle', 's-1000-thunderhead-assault-rifle');
SELECT 'and every one cites Warlords of Russia' AS assertion, count(*) AS got, 35 AS want
